import '@servicenow/sdk/global'
import { StringColumn } from '@servicenow/sdk/core'
import { Flow, wfa, FlowObject } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'
import { ActionDefinition } from '@servicenow/sdk/automation'

// -----------------------------------------------------------------------------
// Action with nested FlowObject input (user.address)
// -----------------------------------------------------------------------------
export const nestedUserAction = ActionDefinition({
    $id: Now.ID['act_nested_user'],
    name: 'Nested User Action',
    category: 'Examples',
    annotation: 'Takes a nested FlowObject and echoes',
    inputs: {
        user: FlowObject({
            label: 'User',
            mandatory: true,
            fields: {
                name: StringColumn({ label: 'Name', mandatory: true }),
                email: StringColumn({ label: 'Email', mandatory: true }),
                address: FlowObject({
                    label: 'Address',
                    mandatory: true,
                    fields: {
                        street: StringColumn({ label: 'Street', mandatory: true }),
                        city: StringColumn({ label: 'City', mandatory: true }),
                    },
                }),
            },
        }),
        note: StringColumn({ label: 'Note', mandatory: false }),
    },
    outputs: {
        success: StringColumn({ label: 'Result', mandatory: true }),
    },
})

// -----------------------------------------------------------------------------
// Flow definition that calls the Action
// -----------------------------------------------------------------------------
Flow(
    {
        $id: Now.ID['flow_nested_object_example'],
        name: 'Flow - Nested FlowObject Example',
        description: 'Calls action with nested FlowObject input',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trg_nested'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    () => {
        wfa.action(
            nestedUserAction,
            { $id: Now.ID['act_inst_nested_user'] },
            {
                user: {
                    name: 'Bob',
                    email: 'bob@example.com',
                    address: { street: '123 Main', city: 'Metropolis' },
                },
                note: 'hello',
            }
        )
    }
)
